CREATE DATABASE IF NOT EXISTS benkeyshop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE benkeyshop;
CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY AUTO_INCREMENT,sku VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,price DECIMAL(14,2) NOT NULL,stock INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales(id BIGINT PRIMARY KEY AUTO_INCREMENT,receipt_no VARCHAR(40) NOT NULL UNIQUE,buyer_name VARCHAR(120) NOT NULL,sold_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,subtotal DECIMAL(14,2) NOT NULL,discount DECIMAL(14,2) NOT NULL DEFAULT 0,total DECIMAL(14,2) NOT NULL,paid DECIMAL(14,2) NOT NULL,change_amount DECIMAL(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS sale_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,sale_id BIGINT NOT NULL,product_id BIGINT NULL,sku_snapshot VARCHAR(40) NOT NULL,product_name_snapshot VARCHAR(120) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,quantity INT NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
